import networkx as nx
import itertools

def find_graph():
    for edges in itertools.combinations(itertools.combinations(range(9), 2), 12):
        G = nx.Graph()
        G.add_edges_from(edges)
        if all(degree >= 2 for degree in (G.degree(node) for node in G.nodes)) and all(degree <= 3 for degree in (G.degree(node) for node in G.nodes)):
            if nx.algorithms.coloring.greedy_color(G) <= 4 and nx.algorithms.coloring.greedy_color(G) >= 2:
                if (0, 8) in G.edges and (6, 7) in G.edges:
                    return list(G.edges)
    return "UNSATISFIABLE"

print(find_graph())
